<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue'
import {Button,FormControl,ErrorMessage,Badge} from '@relay/ui'
import { useRealtimeRefresh } from '../composables/useRealtimeRefresh'
import {coreApi} from '../services/coreApi'
const rows=ref([]),query=ref(''),next=ref(null),error=ref(''),busy=ref(false),manage=ref(false);let timer,generation=0
async function load(after){const current=++generation;busy.value=true;error.value='';try{const result=await coreApi('canned_replies.directory',{query:query.value,after});if(current===generation){rows.value=after?[...rows.value,...result.items]:result.items;next.value=result.next;manage.value=result.can_configure}}catch(e){if(current===generation)error.value=e.message}finally{if(current===generation)busy.value=false}}
watch(query,()=>{clearTimeout(timer);++generation;timer=setTimeout(()=>load(),300)});onMounted(()=>load());onBeforeUnmount(()=>{clearTimeout(timer);++generation})
useRealtimeRefresh(['Relay Canned Reply'], ['canned_replies'], () => load())
</script>
<template><section class="page-body"><div class="flex flex-wrap gap-3 items-center mb-5"><a v-if="manage" class="text-sm underline" href="/desk/relay-canned-reply/new">Create in Desk ↗</a></div><p class="text-sm text-ink-gray-5 mb-4">Published WhatsApp replies are available from Saved replies in the chat composer.</p><FormControl label="Search saved replies" v-model="query"/><ErrorMessage :message="error"/><div class="grid gap-3 mt-4"><article v-for="row in rows" :key="row.name" class="border border-outline-gray-2 rounded-lg p-4 space-y-2"><div class="flex gap-3"><strong>{{row.title}}</strong><Badge :label="row.published?'Published':'Draft'"/><span class="text-xs text-ink-gray-5">{{row.language}} · {{row.reply_type||'Text'}}</span></div><p class="whitespace-pre-wrap text-sm">{{row.body}}</p><a v-if="manage" class="text-xs underline" :href="'/desk/relay-canned-reply/'+encodeURIComponent(row.name)">Edit in Desk ↗</a></article></div><p v-if="!busy&&!rows.length" class="py-6 text-sm text-ink-gray-5">No matching WhatsApp saved replies.</p><p v-if="busy" role="status">Loading saved replies…</p><Button v-if="next" label="More replies" :loading="busy" @click="load(next)"/></section></template>
